<?php $fs=static fn(string $s):string=>ucfirst(str_replace('_',' ',$s));$mc=static fn(int$v):string=>'R$ '.number_format($v/100,2,',','.'); ?>
<header class="panel-page-heading"><div><span>Reserva #<?= (int)$reserva['id'] ?></span><h1><?= e($reserva['chacara_nome']) ?></h1><p><?= e($reserva['cliente_nome']) ?></p></div><a class="btn btn-outline" href="<?= url('/proprietario/dashboard') ?>">Voltar</a></header>
<section class="panel-card"><dl class="client-summary-list"><div><dt>Status</dt><dd><?= e($fs($reserva['status_reserva'])) ?></dd></div><div><dt>Pagamento</dt><dd><?= e($fs($reserva['status_pagamento'])) ?></dd></div><div><dt>Periodo</dt><dd><?= e(date('d/m/Y',strtotime($reserva['data_inicio']))) ?> a <?= e(date('d/m/Y',strtotime($reserva['data_fim']))) ?></dd></div><div><dt>Diaria liquida</dt><dd><?= e($mc((int)$reserva['valor_diaria_liquido_proprietario_centavos'])) ?></dd></div><div><dt>Quantidade de diarias</dt><dd><?= (int)$reserva['quantidade_diarias'] ?></dd></div><div><dt>Valor que recebera</dt><dd><?= e($mc((int)$reserva['valor_liquido_proprietario_centavos'])) ?></dd></div><div><dt>Status do repasse</dt><dd>Preparado para etapa futura</dd></div></dl><div class="client-detail-actions"><?php if($reserva['status_reserva']==='confirmada'):?><form method="post" action="<?= url('/proprietario/reservas/'.(int)$reserva['id'].'/iniciar') ?>"><?= csrf_field() ?><button class="btn btn-primary">Iniciar locacao</button></form><?php endif;?><?php if($reserva['status_reserva']==='em_andamento'):?><form method="post" action="<?= url('/proprietario/reservas/'.(int)$reserva['id'].'/finalizar') ?>"><?= csrf_field() ?><button class="btn btn-primary">Finalizar locacao</button></form><?php endif;?></div></section>
<section class="panel-card"><div class="panel-card-heading"><h2>Historico</h2></div><?php foreach($historico as$h):?><p><strong><?= e($fs($h['status_novo'])) ?></strong> &middot; <?= e(date('d/m/Y H:i',strtotime($h['criado_em']))) ?></p><?php endforeach;?></section>
